(() => {
    'use strict';

    const instances = new Map();
    const color = value => typeof value === 'string' ? value : '#ffffff';

    class ParticleField {
        constructor(element, configuration = {}) {
            this.element = element;
            this.configuration = configuration;
            this.canvas = document.createElement('canvas');
            this.canvas.className = 'particles-js-canvas-el';
            this.context = this.canvas.getContext('2d');
            this.frame = 0;
            this.particles = [];
            element.querySelectorAll('.particles-js-canvas-el').forEach(canvas => canvas.remove());
            element.append(this.canvas);
            this.resizeHandler = () => this.resize();
            this.resizeObserver = 'ResizeObserver' in window
                ? new ResizeObserver(this.resizeHandler)
                : null;
            this.resizeObserver?.observe(element);
            if (!this.resizeObserver) window.addEventListener('resize', this.resizeHandler, { passive: true });
            this.resize();
            this.createParticles();
            this.draw = this.draw.bind(this);
            this.frame = requestAnimationFrame(this.draw);
        }

        resize() {
            const ratio = Math.min(window.devicePixelRatio || 1, 2);
            const width = Math.max(1, this.element.clientWidth);
            const height = Math.max(1, this.element.clientHeight);
            this.canvas.width = Math.round(width * ratio);
            this.canvas.height = Math.round(height * ratio);
            this.canvas.style.width = `${width}px`;
            this.canvas.style.height = `${height}px`;
            this.context.setTransform(ratio, 0, 0, ratio, 0, 0);
            this.width = width;
            this.height = height;
        }

        createParticles() {
            const settings = this.configuration.particles || {};
            const requested = Number(settings.number?.value) || 80;
            const count = Math.min(250, Math.max(0, requested));
            const size = Number(settings.size?.value) || 3;
            const speed = Number(settings.move?.speed) || 2;
            this.particles = Array.from({ length: count }, () => ({
                x: Math.random() * this.width,
                y: Math.random() * this.height,
                radius: Math.max(0.5, size * (settings.size?.random ? Math.random() : 1)),
                vx: (Math.random() - 0.5) * speed,
                vy: (Math.random() - 0.5) * speed
            }));
        }

        draw() {
            const settings = this.configuration.particles || {};
            const context = this.context;
            context.clearRect(0, 0, this.width, this.height);
            context.fillStyle = color(settings.color?.value);
            const opacity = Number(settings.opacity?.value);
            context.globalAlpha = Number.isFinite(opacity) ? opacity : 1;

            this.particles.forEach(particle => {
                particle.x += particle.vx;
                particle.y += particle.vy;
                if (particle.x < -particle.radius) particle.x = this.width + particle.radius;
                if (particle.x > this.width + particle.radius) particle.x = -particle.radius;
                if (particle.y < -particle.radius) particle.y = this.height + particle.radius;
                if (particle.y > this.height + particle.radius) particle.y = -particle.radius;
                context.beginPath();
                context.arc(particle.x, particle.y, particle.radius, 0, Math.PI * 2);
                context.fill();
            });

            const links = settings.line_linked || {};
            if (links.enable) {
                const distance = Number(links.distance) || 100;
                context.strokeStyle = color(links.color);
                context.lineWidth = Number(links.width) || 1;
                for (let first = 0; first < this.particles.length; first += 1) {
                    for (let second = first + 1; second < this.particles.length; second += 1) {
                        const a = this.particles[first];
                        const b = this.particles[second];
                        const length = Math.hypot(a.x - b.x, a.y - b.y);
                        if (length > distance) continue;
                        context.globalAlpha = (Number(links.opacity) || 1) * (1 - length / distance);
                        context.beginPath();
                        context.moveTo(a.x, a.y);
                        context.lineTo(b.x, b.y);
                        context.stroke();
                    }
                }
            }
            context.globalAlpha = 1;
            this.frame = requestAnimationFrame(this.draw);
        }

        destroy() {
            cancelAnimationFrame(this.frame);
            this.resizeObserver?.disconnect();
            window.removeEventListener('resize', this.resizeHandler);
            this.canvas.remove();
            instances.delete(this.element.id);
        }
    }

    window.particlesJS = (id = 'particles-js', configuration = {}) => {
        const element = document.getElementById(typeof id === 'string' ? id : 'particles-js');
        if (!element) return null;
        if (typeof id !== 'string') configuration = id;
        instances.get(element.id)?.destroy();
        const instance = new ParticleField(element, configuration);
        instances.set(element.id, instance);
        return instance;
    };
    window.particlesJS.instances = instances;
})();
